// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { PrepareOrchestration, type PrepareOrchestrationInput } from "@godseye/contracts";
import { describe, expect, it } from "vitest";

const hermes = (id = "research", dependsOn: string[] = []) => ({
  id,
  dependsOn,
  kind: "hermes" as const,
  profileId: randomUUID(),
  expectedRevision: 1,
  input: "Research the declared scope",
});
const input = (): PrepareOrchestrationInput => ({
  projectId: randomUUID(),
  environmentId: randomUUID(),
  expectedProjectRevision: 1,
  expectedEnvironmentRevision: 1,
  title: "Bounded research",
  maxCostMicros: 10000,
  lifetimeSeconds: 300,
  steps: [hermes()],
});

describe("bounded untrusted orchestration plan contract", () => {
  it("T-AC-701 accepts a finite DAG with all three typed step kinds", () => {
    const plan = input();
    plan.steps.push(
      {
        id: "question",
        dependsOn: ["research"],
        kind: "clarification",
        question: "Which variant?",
      },
      {
        id: "patch",
        dependsOn: ["question"],
        kind: "coding",
        preparationId: randomUUID(),
        expectedHash: "a".repeat(64),
      },
    );
    expect(PrepareOrchestration.parse(plan)).toEqual(plan);
  });

  it.each([
    { name: "duplicate IDs", steps: [hermes(), hermes()] },
    { name: "unknown dependencies", steps: [hermes("a", ["missing"])] },
    { name: "self dependency", steps: [hermes("a", ["a"])] },
    { name: "two-node cycle", steps: [hermes("a", ["b"]), hermes("b", ["a"])] },
    { name: "duplicate dependency", steps: [hermes("a"), hermes("b", ["a", "a"])] },
    { name: "empty plan", steps: [] },
    { name: "too many steps", steps: Array.from({ length: 13 }, (_, n) => hermes(`step-${n}`)) },
    { name: "unknown authority field", steps: [{ ...hermes(), shell: "untrusted-command" }] },
    { name: "UTF8 text overflow", steps: [{ ...hermes(), input: "😀".repeat(2049) }] },
    {
      name: "aggregate UTF8 overflow",
      steps: Array.from({ length: 9 }, (_, n) => ({
        ...hermes(`step-${n}`),
        input: "é".repeat(4096),
      })),
    },
  ])("T-AC-701 rejects $name", ({ steps }) => {
    expect(PrepareOrchestration.safeParse({ ...input(), steps }).success).toBe(false);
  });

  it("T-AC-701 accepts exactly the text byte boundary and rejects one extra byte", () => {
    const plan = input();
    expect(
      PrepareOrchestration.safeParse({ ...plan, steps: [{ ...hermes(), input: "é".repeat(4096) }] })
        .success,
    ).toBe(true);
    expect(
      PrepareOrchestration.safeParse({
        ...plan,
        steps: [{ ...hermes(), input: `${"é".repeat(4096)}a` }],
      }).success,
    ).toBe(false);
  });

  it("T-AC-701 preserves acyclicity across deterministic dependency graph variations", () => {
    for (let length = 2; length <= 12; length++) {
      const steps = Array.from({ length }, (_, n) => hermes(`s${n}`, n === 0 ? [] : [`s${n - 1}`]));
      expect(PrepareOrchestration.safeParse({ ...input(), steps }).success).toBe(true);
      const first = steps[0];
      if (!first) throw new Error("Missing generated DAG step");
      first.dependsOn = [`s${length - 1}`];
      expect(PrepareOrchestration.safeParse({ ...input(), steps }).success).toBe(false);
    }
  });
});
